/* preview-guard.js — حارس المعاينة (يُولَّد ببناء المعاينة فقط؛ ليس في المشروع): أي طلب كتابة للخادم يُرفض داخل الجوال
 * ولا يخرج، وتُعرض شارة «معاينة — للقراءة فقط». The preview guard (generated by the preview build only): any write request
 * is refused on the device and never sent; a «preview — read only» badge shows. */
(function (global) {
  'use strict';
  const API = global.SEC2_CONFIG.API_BASE_URL;
  const BLOCKED = ["addNewStation","updateCoordinates","deleteStation","updateMemberProfile","registerUser","registerCredential","generateRegisterChallenge","clearSearchCache","logClientError"];
  const MSG = 'المعاينة للقراءة فقط — لا إضافة ولا تعديل ولا حذف من نسخة المعاينة';
  const realFetch = global.fetch.bind(global);
  global.__previewBlocked = [];
  global.fetch = function (input, init) {
    const url = typeof input === 'string' ? input : (input && input.url) || '';
    if (url.indexOf(API) === 0 && init && typeof init.body === 'string') {
      let action = '';
      try { action = JSON.parse(init.body).action || ''; } catch (e) { action = ''; }
      if (BLOCKED.indexOf(action) !== -1) {
        global.__previewBlocked.push(action);
        const reply = action === 'logClientError' ? { success: true, logged: 0 } : { success: false, error: MSG };
        return Promise.resolve(new Response(JSON.stringify(reply), { status: 200, headers: { 'Content-Type': 'application/json' } }));
      }
    }
    return realFetch(input, init);
  };
  global.document.addEventListener('DOMContentLoaded', function () {
    const b = global.document.createElement('div');
    b.className = 'preview-badge'; b.textContent = 'معاينة — للقراءة فقط';
    b.setAttribute('style', 'position:fixed;top:calc(env(safe-area-inset-top,0px) + 4px);left:50%;transform:translateX(-50%);z-index:2000;' +
      'padding:3px 12px;border-radius:12px;background:#E5484D;color:#fff;font:700 12px/1.4 sans-serif;cursor:pointer;opacity:.92;');
    global.document.body.appendChild(b);
    // لوحة قياسات للمعاينة فقط (الضغط على الشارة): الشاشة، الصفحة، الفراغ، المنطقتان الآمنتان — preview-only measurements panel
    b.addEventListener('click', function () {
      const old = global.document.getElementById('previewDiag');
      if (old) { old.remove(); global.document.querySelectorAll('.previewDiagLine').forEach(function (l) { l.remove(); }); return; }
      const probe = global.document.createElement('div');
      probe.setAttribute('style', 'position:fixed;visibility:hidden;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);');
      global.document.body.appendChild(probe);
      const cs = getComputedStyle(probe), fixedH = (function () { const p = global.document.createElement('div'); p.setAttribute('style', 'position:fixed;top:0;bottom:0;width:1px;visibility:hidden;'); global.document.body.appendChild(p); const h = p.getBoundingClientRect().height; p.remove(); return h; })();
      const rows = [['تطبيق مثبّت', String(global.navigator.standalone === true)], ['ارتفاع الشاشة', global.screen.height], ['ارتفاع الصفحة', global.innerHeight],
        ['منطقة العناصر الثابتة', Math.round(fixedH)], ['الفراغ المعالَج', getComputedStyle(global.document.documentElement).getPropertyValue('--ios-gap').trim() || '0px'],
        ['الآمنة العلوية', cs.paddingTop], ['الآمنة السفلية', cs.paddingBottom]];
      probe.remove();
      // (21 أكتوبر) قياسات إضافية لتحديد موضع الصفحة على الشاشة — extra readings to locate the page on the screen
      const unitH = function (u) { const p = global.document.createElement('div'); p.setAttribute('style', 'position:absolute;top:0;width:1px;visibility:hidden;height:100' + u + ';'); global.document.body.appendChild(p); const h = Math.round(p.getBoundingClientRect().height); p.remove(); return h; };
      const vv = global.visualViewport, nav = global.document.querySelector('.bottom-nav'), nr = nav ? nav.getBoundingClientRect() : null;
      rows.push(['svh / dvh / lvh / vh', unitH('svh') + ' / ' + unitH('dvh') + ' / ' + unitH('lvh') + ' / ' + unitH('vh')],
        ['العرض المرئي: الارتفاع / الإزاحة', vv ? Math.round(vv.height) + ' / ' + Math.round(vv.offsetTop) : '—'],
        ['التمرير / clientHeight / availHeight', Math.round(global.scrollY) + ' / ' + global.document.documentElement.clientHeight + ' / ' + global.screen.availHeight],
        ['الشريط السفلي: أعلى / أسفل', nr ? Math.round(nr.top) + ' / ' + Math.round(nr.bottom) : '—'],
        ['المسافة تحت أيقونات الشريط', nav ? getComputedStyle(nav).paddingBottom : '—']);
      // خطان مؤقتان: أزرق عند أعلى منطقة العناصر الثابتة، وأحمر عند أسفلها — two temporary lines at the fixed area's top and bottom
      [['top', '#2E7DD1'], ['bottom', '#E5484D']].forEach(function (x) {
        const l = global.document.createElement('div'); l.className = 'previewDiagLine';
        l.setAttribute('style', 'position:fixed;left:0;right:0;height:4px;z-index:2002;pointer-events:none;' + x[0] + ':0;background:' + x[1] + ';');
        global.document.body.appendChild(l);
      });
      const d = global.document.createElement('div'); d.id = 'previewDiag';
      d.setAttribute('style', 'position:fixed;top:calc(env(safe-area-inset-top,0px) + 30px);left:50%;transform:translateX(-50%);z-index:2001;background:#111A;' +
        'color:#fff;font:700 13px/1.7 sans-serif;padding:10px 14px;border-radius:12px;direction:rtl;background:rgba(10,16,26,.92);');
      d.innerHTML = rows.map(function (r) { return '<div>' + r[0] + ': <b dir="ltr">' + r[1] + '</b></div>'; }).join('') +
        // تجارب الطبقة الضبابية أعلى الشاشة (22 أكتوبر) — the top haze experiments
        '<div style="margin-top:8px;display:flex;flex-direction:column;gap:6px">' + EXPS.map(function (x) {
          const on = exps_().indexOf(x[0]) !== -1;
          return '<button type="button" data-exp="' + x[0] + '" style="font:700 13px sans-serif;padding:8px 10px;border-radius:10px;border:none;' +
            'background:' + (on ? '#1FAE8C' : '#3A4757') + ';color:#fff">' + (on ? '✓ ' : '') + x[1] + '</button>';
        }).join('') + '</div>';
      d.addEventListener('click', function (e) {
        const t = e.target.closest('[data-exp]'); if (!t) return;
        const list = exps_(), k = t.dataset.exp, i = list.indexOf(k);
        if (i === -1) list.push(k); else list.splice(i, 1);
        try { global.localStorage.setItem(EXP_KEY, list.join(',')); } catch (err) { /* لا شيء / nothing */ }
        global.location.reload();
      });
      global.document.body.appendChild(d);
    });
    applyExps_();
  });
  // ===== تجارب الطبقة الضبابية (المعاينة وحدها، تُحفظ في جهاز المعاينة) — the haze experiments (preview only, saved on the device) =====
  const EXP_KEY = 'sec2p-exp';
  const EXPS = [['noscroll', 'تجربة 1: بلا تمرير في الخريطة'], ['topcolor', 'تجربة 2: شريط الساعة بلون الخلفية']];
  function exps_() { try { return String(global.localStorage.getItem(EXP_KEY) || '').split(',').filter(Boolean); } catch (e) { return []; } }
  function applyExps_() {
    const on = exps_(), css = [];
    if (on.indexOf('noscroll') !== -1) css.push('html:has(body.home-page[data-view="map"]),body.home-page[data-view="map"]{overflow:hidden;}');
    if (on.indexOf('topcolor') !== -1) css.push('body.home-page::before{content:"";position:fixed;top:0;left:0;right:0;height:env(safe-area-inset-top,0px);background:var(--bg);z-index:1000;pointer-events:none;}');
    if (!css.length) return;
    const st = global.document.createElement('style'); st.textContent = css.join(' '); global.document.head.appendChild(st);
  }
})(window);
